echo '<script>

function populateSelect(){

	var hostteste = window.location.host;

	if (hostteste.match("localhost")) {
		hostName = "http://sp.maua.homo.millenio.com.br";

	} else if (hostteste.match("homo")) {
		hostName = "http://sp.maua.homo.millenio.com.br";

	} else if (hostteste.match("devs")) {
		hostName = "http://sp.maua.devs.millenio.com.br";

	}	else if (hostteste.match("webgis")) {
		hostName = "https://webgis.maua.sp.gov.br";

	}   else if (hostteste.match("maua")) {
		hostName = "https://maua.millenio.com.br";

	}

	$.ajax({
		type: "GET",
		url: hostName+"/data/t_users_groups?select=name_groups&name_users=eq." + $("#username").val(),
		success : function(data) { 
			if (data != "" && data != undefined) {
				var html="";
				for(var i=0; i<data.length; i++){
					html +="<option>"+data[i]["name_groups"]+"</option>";
				}
				html +="<option>"+""+"</option>";
				$("#gruposLogin").html(html);

			} else {
				//alert("Email/Usuário não localizado!");
				if ($("#username").val()) {
					modal_alert("Alerta", "usuário não localizado ou incorreto!");
					var html="";
					$("#datagrupo").html(html);
				}
			}
		}
	});
};

</script>';
